package com.kartyavya.report.controller; import com.kartyavya.report.service.ReportService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/dashboard") public class DashboardController{private final ReportService s;public DashboardController(ReportService s){this.s=s;}@GetMapping("/citizen")Map<String,Object> citizen(Authentication a){return s.citizenDashboard(a);}@GetMapping("/admin")Map<String,Object> admin(){return s.adminDashboard();}}
